/// The registry's table streams by name, which a query binds its sources to
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `name` - The registry's name (e.g. `models`)
///
/// Returns
/// * The registry's spec name, version and table streams
pub async fn tables(ctx: &dyn RequestContext, name: &str) -> Result<RegistryTables, Error> {
    let path = "/v1/api/ulv2/registry/:name".replace(":name", name);
    let res = ctx.get(&path, None, None).await?;
    crate::types::RegistryTables::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Project one governed object into the registry: read its referenced source, verify the hash, extract the declared fields. Idempotent per (object, source hash).
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `name` - The registry's name (e.g. `models`)
/// * `object_id` - The governed object to project
///
/// Returns
/// * What was projected
pub async fn project(
    ctx: &dyn RequestContext,
    name: &str,
    object_id: crate::types::id::ObjectId,
) -> Result<ProjectResult, Error> {
    let path = "/v1/api/ulv2/registry/:name/project/:object_id"
        .replace(":name", name)
        .replace(":object_id", &object_id.to_string());
    let body = Bytes::new();
    let res = ctx.post(&path, body, "text/plain", None, None).await?;
    crate::types::ProjectResult::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Tombstone one object's rows in the registry (its history stays); the caller must be able to modify the object.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `name` - The registry's name (e.g. `models`)
/// * `object_id` - The governed object to tombstone
///
/// Returns
/// * The tombstone written
pub async fn unlink(
    ctx: &dyn RequestContext,
    name: &str,
    object_id: crate::types::id::ObjectId,
) -> Result<ProjectResult, Error> {
    let path = "/v1/api/ulv2/registry/:name/:object_id"
        .replace(":name", name)
        .replace(":object_id", &object_id.to_string());
    let res = ctx.delete(&path, None, None).await?;
    crate::types::ProjectResult::from_fbs_bytes(res.as_slice()).map_err(Error::from)
}

/// Query the registry as the caller: the Query's bound sources name the registry's tables; rows are the newest per key and filtered by the objects' ACLs. Apache Arrow IPC stream out.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `name` - The registry's name (e.g. `models`)
/// * `query` - The query to execute; its table sources are registry table names
///
/// Returns
/// * The rows the caller may see
pub async fn query_arrow(
    ctx: &dyn RequestContext,
    name: &str,
    query: Query,
) -> Result<Vec<arrow::record_batch::RecordBatch>, Error> {
    let path = "/v1/api/ulv2/registry/:name/query".replace(":name", name);
    let mut headers = HeaderMap::new();
    headers.insert(
        HeaderName::from_static("accept"),
        HeaderValue::from_static("application/vnd.apache.arrow.stream"),
    );

    let body = Bytes::from(query.to_fbs_bytes());
    let res = ctx
        .post(&path, body, "application/octet-stream", None, Some(headers))
        .await?;
    read_arrow_ipc(&res)
}

